<?php
// Calls that leave the node under its first parent keep the finding.
function otherChild() { $d = new DOMDocument(); $a = $d->createElement('a'); $b = $d->createElement('b'); $n = $d->createElement('n'); $z = $d->createTextNode('z'); $a->appendChild($z); $a->appendChild($n); $a->removeChild($z); <warning descr="Clone the node when preserving its existing parent.">$b->appendChild($n)</warning>; }
function otherClone() { $d = new DOMDocument(); $a = $d->createElement('a'); $b = $d->createElement('b'); $n = $d->createElement('n'); $z = $n->cloneNode(true); $a->appendChild($z); $a->appendChild($n); $a->replaceChild($d->createElement('y'), $z); <warning descr="Clone the node when preserving its existing parent.">$b->appendChild($n)</warning>; }
function otherNode() { $d = new DOMDocument(); $a = $d->createElement('a'); $b = $d->createElement('b'); $n = $d->createElement('n'); $z = $d->createElement('z'); $a->appendChild($n); $z->remove(); <warning descr="Clone the node when preserving its existing parent.">$b->appendChild($n)</warning>; }
function otherParent() { $d = new DOMDocument(); $a = $d->createElement('a'); $b = $d->createElement('b'); $n = $d->createElement('n'); $z = $d->createElement('z'); $b->appendChild($z); $a->appendChild($n); $b->removeChild($z); $b->replaceChildren(); <warning descr="Clone the node when preserving its existing parent.">$b->appendChild($n)</warning>; }
function parentRemoved() { $d = new DOMDocument(); $a = $d->createElement('a'); $b = $d->createElement('b'); $n = $d->createElement('n'); $a->appendChild($n); $a->remove(); $d->saveXML(); <warning descr="Clone the node when preserving its existing parent.">$b->appendChild($n)</warning>; }
